function apply(value){if(['ru','en','he'].indexOf(value)<0)value='ru';lang=value;document.documentElement.lang=lang;document.documentElement.dir=lang==='he'?'rtl':'ltr';try{localStorage.setItem('watch_language',lang);}catch(e){}if(observer)observer.disconnect();if(baseTitle===null)baseTitle=document.title;document.title=translate(baseTitle);tree(document.body);document.querySelectorAll('[data-lang]').forEach(function(b){b.setAttribute('aria-pressed',String(b.dataset.lang===lang));});observe();window.dispatchEvent(new CustomEvent('watch-language-change',{detail:{language:lang}}));}
